/* {--friendster-layouts.com css code start--} */

/* FRIENDSTER-LAYOUTS.COM */
/* looking into fantasy by shirahime shou */

/* PAGE BACKGROUND */
body {
  background-image: url(http://i200.photobucket.com/albums/aa73/fs-layouts/fslybg/2007/06/looking-into-fantasy.jpg);
  background-attachment: fixed;
  background-position: bottom right;
  background-repeat: no-repeat;
  background-color: #130f12;
}
/* GLOBAL FONTS */
.usercontent {
  font-family: Arial, Geneva, Helvetica, sans-serif;
  color: #ff33cc;
}
/* GLOBAL LINKS */
.usercontent a, .usercontent a:link, .usercontent a:visited, .usercontent a:hover, .usercontent a:active {
  color: #ff99ff;
}
.usercontent a:hover {
  text-decoration: none;
  color: #ff3366;
}
/* MASTER BOXES */
.commonbox {
  border-width: 2px;
  border-color: #ff3333;
  border-style: dashed;
  background-color: transparent;
}
.commonbox .evenrow {
  background-color: transparent;
}
/* MASTER HEADERS */
.commonbox h1, .commonbox h2 {
  font-family: Trebuchet MS, Geneva, Arial, Helvetica, SunSans-Regular, sans-serif;
  color: #ff3366;
  background-color: #ff99ff;
}
/* CONTROL PANEL: BOX */
.controlpanel {
  border-width: 2px;
  border-color: #ff3300;
  border-style: dotted;
  background-color: transparent;
}
/* CONTROL PANEL: USER PHOTO */
.controlpanel .imgblock200 {
  border-color: #ffffff;
}
/* CONTROL PANEL: DATA */
.controlpanel .q {
  font-family: Arial, Geneva, Helvetica, sans-serif;
  color: #ffffff;
}
.controlpanel .data {
  font-family: Trebuchet MS, Geneva, Arial, Helvetica, SunSans-Regular, sans-serif;
  color: #ff3366;
}
.data a {
  font-family: Arial, Geneva, Helvetica, sans-serif;
  color: #ff33ff;
}
/* CONTROL PANEL: MORE ABOUT ME LINK */
a.more {
  font-family: Arial, Geneva, Helvetica, sans-serif;
  color: #ff3399;
}
/* CONTROL PANEL: BUTTONS */
#controlPanelButtons a, #controlPanelButtons a:link, #controlPanelButtons a:visited {
  font-family: Trebuchet MS, Geneva, Arial, Helvetica, SunSans-Regular, sans-serif;
  color: #ffffff;
  border-color: #ff99ff;
  border-style: dotted;
  background-color: transparent;
}
#controlPanelButtons a:hover {
  font-family: Trebuchet MS, Geneva, Arial, Helvetica, SunSans-Regular, sans-serif;
  color: #ff3333;
  border-color: #ffffff;
  background-color: #ff99ff;
  text-decoration: underline;
}
/* MISC: TESTIMONIALS/REVIEWS TEXT */
.data {
  font-family: Verdana, Arial, Helvetica, sans-serif;
  color: #ff9999;
}
/* MISC: VIEW ALL LINKS */
.commonbox .viewall {
  font-family: Courier New, Courier, Monaco, monospace;
  color: #ffffff;
}
/* MISC: SMALL PHOTOS */
.commonbox .imgblock75, .ir {
  border-width: 2px;
  border-color: #ffffff;
  border-style: double;
  background-color: transparent;
}
/* MISC: SMALL PHOTO NAMES */
.commonbox .dr {
  color: #ffffff;
  background-color: transparent;
}

/* {--friendster-layouts.com css code end--} */
